import readline from 'node:readline';const rl=readline.createInterface({input:process.stdin});rl.once('line',line=>{const r=JSON.parse(line);console.log(JSON.stringify({schemaVersion:'fs.decision.result.v1',provider:'fixture',answers:r.questions.map(q=>q.type==='noul'?{id:q.id,type:q.type,distribution:{false:.2,true:.8},probabilityTrue:.8,confidence:.8,abstained:false,reason:'fixture'}:{id:q.id,type:q.type,distribution:Object.fromEntries((q.options??q.levels).map((x,i)=>[x,i?0:1])),selected:(q.options??q.levels)[0],confidence:.8,abstained:false,reason:'fixture'}),evidence:{stateSchemaVersion:r.state.schemaVersion,providerVersion:'fixture',policyVersion:'none',authoritative:false,notes:[]},createdAt:new Date().toISOString()}));process.exit(0)});
